# Extracting the Domain from a URL in JavaScript

## Recommended Approach: Use the `URL` API

The modern and most reliable way is to use the built-in `URL` constructor:

```javascript
function getDomain(url) {
  try {
    const parsedUrl = new URL(url);
    return parsedUrl.hostname;
  } catch (error) {
    console.error("Invalid URL:", error);
    return null;
  }
}

// Examples
console.log(getDomain("https://www.example.com/path/to/page"));
// Output: "www.example.com"

console.log(getDomain("http://subdomain.example.org:8080"));
// Output: "subdomain.example.org"

console.log(getDomain("https://example.com"));
// Output: "example.com"
```

## Get Only the Registered Domain (Strip Subdomain)

If you want the **root domain** (e.g., `example.com` instead of `www.example.com`):

```javascript
function getRootDomain(url) {
  try {
    const parsedUrl = new URL(url);
    let hostname = parsedUrl.hostname;

    // Remove 'www.' prefix if present
    hostname = hostname.replace(/^www\./, "");

    // Handle known public suffixes (basic example)
    // For production, use a library like `tldts` or `public-suffix-list`
    const parts = hostname.split(".");
    if (parts.length >= 2) {
      // For simple .com/.org/.net domains
      if ([".com", ".org", ".net", ".edu", ".gov"].some(suffix => 
          hostname.endsWith(suffix))) {
        return parts.slice(-2).join(".");
      }
      // For multi-part TLDs like .co.uk, use a proper TLD library
    }

    return hostname;
  } catch (error) {
    console.error("Invalid URL:", error);
    return null;
  }
}

