```c
#include <stdio.h>

int main() {
    FILE *file = fopen("file.txt", "r");
    if (file != NULL) {
        char firstLine[256];
        if (fgets(firstLine, sizeof(firstLine), file) != NULL) {
            printf("%s", firstLine);
        }
        fclose(file);
    } else {
        printf("Unable to open file.\n");
    }
    return 0;
}
