# Matrix Multiplication in Kotlin

Here's how to multiply two matrices in Kotlin:

## Implementation

```kotlin
import kotlin.math.roundToInt

/**
 * Multiplies two matrices.
 *
 * @param a First matrix (m x n)
 * @param b Second matrix (n x p)
 * @return Resulting matrix (m x p)
 * @throws IllegalArgumentException if dimensions don't allow multiplication
 */
fun multiplyMatrices(a: Array<DoubleArray>, b: Array<DoubleArray>): Array<DoubleArray> {
    val m = a.size
    val n = a[0].size
    val p = b[0].size

    // Validate dimensions: columns of A must equal rows of B
    if (n != b.size) {
        throw IllegalArgumentException(
            "Matrix dimensions incompatible for multiplication: " +
            "A is $m x $n, B is ${b.size} x $p"
        )
    }

    val result = Array(m) { DoubleArray(p) }

    for (i in 0 until m) {
        for (j in 0 until p) {
            var sum = 0.0
            for (k in 0 until n) {
                sum += a[i][k] * b[k][j]
            }
            result[i][j] = sum
        }
    }

    return result
}
```

## Example Usage

```kotlin
fun main() {
    // 2x3 matrix
    val a = arrayOf(
        doubleArrayOf(1.0, 2.0, 3.0),
        doubleArrayOf(4.0, 5.0, 6.0)
    )

    // 3x2 matrix
    val b = arrayOf(
        doubleArrayOf(7.0, 8.0),
        doubleArrayOf(9.0, 10.0),
        doubleArrayOf(11.0, 12.0)
    )

    val result = multiplyMatrices(a, b)

    // Print result
    result.forEach { row ->
        println(row.joinToString(" ") { String.format("%.2f", it) })
    }
}
```

