# Remove Duplicates from an Array

Here are several approaches to remove duplicates from an array in JavaScript:

## 1. Using `Set` (Most Concise)

```javascript
function removeDuplicates(arr) {
  return [...new Set(arr)];
}

// Example
const nums = [1, 2, 2, 3, 4, 4, 5];
console.log(removeDuplicates(nums)); // [1, 2, 3, 4, 5]
```

## 2. Using `filter()` and `indexOf()`

```javascript
function removeDuplicates(arr) {
  return arr.filter((item, index) => arr.indexOf(item) === index);
}

// Example
console.log(removeDuplicates([1, 2, 2, 3, 4, 4, 5])); // [1, 2, 3, 4, 5]
```

## 3. Using a `Map` or `Object` for Complex Objects

```javascript
function removeDuplicatesBy(arr, keyFn) {
  const seen = new Map();
  return arr.filter(item => {
    const key = keyFn(item);
    if (seen.has(key)) return false;
    seen.set(key, true);
    return true;
  });
}

// Example with objects
const people = [
  { name: "Alice", age: 30 },
  { name: "Bob", age: 25 },
  { name: "Alice", age: 30 }
];

console.log(removeDuplicatesBy(people, p => p.name));
// [{ name: "Alice", age: 30 }, { name: "Bob", age: 25 }]
```

## 4. Using `reduce()`

```javascript
function removeDuplicates(arr) {
  return arr.reduce((unique, item) => {
    return unique.includes(item) ? unique : [...unique, item];
  }, []);
}

// Example
console.log(removeDuplicates([1, 2, 2, 3, 4, 4, 5])); // [1, 2, 3, 4, 5]
```

