```

## Method 4: Using `for...of` Loop

```javascript
function sumArray(arr) {
  let total = 0;
  for (const num of arr) {
    total += num;
  }
  return total;
}

console.log(sumArray([1, 2, 3, 4, 5])); // 15
```

## Handling Edge Cases

```javascript
function sumArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return 0;
  return arr.reduce((acc, curr) => acc + curr, 0);
}

