  console.log('Button clicked!');
}
```

> ⚠️ **Not recommended** — mixes HTML and JavaScript, hard to maintain.

---

## 3. DOM Property Handler

```javascript
const button = document.getElementById('myButton');
button.onclick = function(event) {
  console.log('Button clicked!');
};
```

> ⚠️ **Limitation**: Only one handler can be assigned this way. Later assignments overwrite previous ones.

---

## 4. Event Delegation (for dynamically added elements)

```javascript
document.getElementById('parentContainer').addEventListener('click', function(event) {
  if (event.target.matches('.child-button')) {
    console.log('Child button clicked!');
  }
});
```

> ✅ Useful when elements are added dynamically or when many similar elements exist.

---

## 5. Multiple Handlers on the Same Element

```javascript
const button = document.getElementById('myButton');

button.addEventListener('click', handlerA);
button.addEventListener('click', handlerB);

function handlerA(event) {
  console.log('Handler A');
}

function handlerB(event) {
  console.log('Handler B');
}
// Both handlers execute when clicked (in order of registration)
```

