# Check if a String is a Valid IP Address

Here are solutions for both **IPv4** and **IPv6** validation in several languages.

---

## Python

```python
import ipaddress

def is_valid_ipv4(ip: str) -> bool:
    """Check if a string is a valid IPv4 address."""
    try:
        ipaddress.IPv4Address(ip)
        return True
    except ipaddress.AddressValueError:
        return False

def is_valid_ipv6(ip: str) -> bool:
    """Check if a string is a valid IPv6 address."""
    try:
        ipaddress.IPv6Address(ip)
        return True
    except ipaddress.AddressValueError:
        return False

def is_valid_ip(ip: str, version: int = 4) -> bool:
    """Check if a string is a valid IPv4 (default) or IPv6 address."""
    if version == 4:
        return is_valid_ipv4(ip)
    elif version == 6:
        return is_valid_ipv6(ip)
    else:
        raise ValueError("Version must be 4 or 6")

# Manual validation (no imports)
def is_valid_ipv4_manual(ip: str) -> bool:
    """Manual IPv4 validation."""
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Each part must be a number between 0 and 255
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':  # No leading zeros
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

# Usage
