import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> myList = new ArrayList<>();

        if (myList.isEmpty()) {
            System.out.println("The list is empty.");
        } else {
            System.out.println("The list is not empty.");
        }
    }
}
```

